import{_ as t,o as i,c as o,ag as a}from"./chunks/framework.D9ghT4bC.js";const r="/Unciv/assets/%E5%9B%BE%E7%89%871.XdmhAzYE.jpg",s="/Unciv/assets/%E5%9B%BE%E7%89%872.DxMNRwV9.jpg",n="/Unciv/assets/%E5%9B%BE%E7%89%873.Bhqh77vu.jpg",l="/Unciv/assets/%E5%9B%BE%E7%89%874.BA9lWuCW.jpg",d="/Unciv/assets/%E5%9B%BE%E7%89%875.DNDU4PT_.jpg",u="/Unciv/assets/%E5%9B%BE%E7%89%876.D54I6TBR.jpg",c="/Unciv/assets/%E5%9B%BE%E7%89%877.DLPAaOGv.jpg",h="/Unciv/assets/%E5%9B%BE%E7%89%878.CpPuut7y.jpg",p="/Unciv/assets/%E5%9B%BE%E7%89%879.DbLTiiy1.png",g="/Unciv/assets/%E5%9B%BE%E7%89%8710.BqraFAOT.png",m="/Unciv/assets/%E5%9B%BE%E7%89%8711.CFmVoHIX.png",b="/Unciv/assets/%E5%9B%BE%E7%89%8712.BdOvmOc8.png",y="/Unciv/assets/%E5%9B%BE%E7%89%8713.Dh5LpFl8.png",f="/Unciv/assets/%E5%9B%BE%E7%89%8714.B3U5DQ9M.png",k="/Unciv/assets/%E5%9B%BE%E7%89%8715.C9ZRWo6I.png",v="/Unciv/assets/%E5%9B%BE%E7%89%8716.CffUMaVE.png",_="/Unciv/assets/%E5%9B%BE%E7%89%8717.DaXmTPAd.png",C=JSON.parse(`{"title":"Gods & Kings Beginner's Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Community/Guides/Gods-and-Kings-guide/index.md","filePath":"Community/Guides/Gods-and-Kings-guide/index.md"}`),q={name:"Community/Guides/Gods-and-Kings-guide/index.md"};function w(x,e,E,P,B,G){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="gods-kings-beginner-s-guide" tabindex="-1">Gods &amp; Kings Beginner&#39;s Guide <a class="header-anchor" href="#gods-kings-beginner-s-guide" aria-label="Permalink to &quot;Gods &amp; Kings Beginner&#39;s Guide&quot;">​</a></h1><blockquote><p>Author: 恶 Editor: SpringPizazz Date: 2024-02-19 Game version: 4.16.0</p></blockquote><h2 id="foreword" tabindex="-1">Foreword <a class="header-anchor" href="#foreword" aria-label="Permalink to &quot;Foreword&quot;">​</a></h2><p>Since newcomers may find Lance&#39;s tutorial hard to follow, I plan to write a basic Unciv introduction myself. I believe that once beginners have a basic understanding of the game, they can understand Lance&#39;s early-war strategy tutorial. To further improve newcomers&#39; skills, I made this basic teaching material, hoping every new player can gain a deep understanding of the game.</p><h2 id="_1-basic-yields" tabindex="-1">1 Basic yields <a class="header-anchor" href="#_1-basic-yields" aria-label="Permalink to &quot;1 Basic yields&quot;">​</a></h2><p><img src="'+r+'" alt="Basic yields"></p><blockquote><p>Note: this chapter is basic content for newcomers. Veterans can skip it.</p></blockquote><p>At the top-right of the game screen you&#39;ll see the key numbers, left to right: <strong>Production/hammer</strong>, <strong>Food/bread</strong>, <strong>Gold</strong>, <strong>Science/bottle</strong>, <strong>Culture/music</strong>, <strong>Faith/dove</strong>.</p><h3 id="_1-1-production" tabindex="-1">1.1 Production <a class="header-anchor" href="#_1-1-production" aria-label="Permalink to &quot;1.1 Production&quot;">​</a></h3><p>Production is vital in Unciv — it&#39;s the basis for building Settlers, Workers, buildings, and military units.</p><p>Example: if a Worker costs 46 production and a city provides 6 per turn, it takes just 8 turns to finish.</p><p>In practice, production rarely matches the cost exactly, so overflow happens often. Overflow isn&#39;t wasted — it carries over to the next build. Food works the same way: surplus food banks toward growth or later builds.</p><h3 id="_1-2-food" tabindex="-1">1.2 Food <a class="header-anchor" href="#_1-2-food" aria-label="Permalink to &quot;1.2 Food&quot;">​</a></h3><p>Food is the second most important number — it directly drives population growth. And population isn&#39;t just a number; it&#39;s tied to many things.</p><ul><li>Each citizen contributes 1 science — population growth indirectly advances tech.</li><li>With trade routes established, each citizen in a secondary city adds ~1 gold to the city&#39;s trade route, making food indirectly boost the economy.</li><li>Militarily, more population means stronger city defense and better supply. All units need supply; going beyond supply range incurs a production penalty.</li></ul><p><img src="'+s+'" alt="Food growth"></p><p>However, food growth isn&#39;t unlimited. When a city&#39;s <strong>happiness</strong> is low, food yield drops by 75%, hugely slowing growth. Early game happiness is scarce, so population can&#39;t keep growing fast.</p><p>Also, as population grows, each new citizen needs more food. In early wars, once the capital reaches ~6 population and secondary cities 4-5, players usually shift focus to production — the food cost of more citizens no longer pays off versus pure production.</p><h3 id="_1-3-gold" tabindex="-1">1.3 Gold <a class="header-anchor" href="#_1-3-gold" aria-label="Permalink to &quot;1.3 Gold&quot;">​</a></h3><p>Gold matters in many ways:</p><ul><li>Upgrading units — a key way to boost military strength.</li><li>Buying units, buildings, or tiles to accelerate development.</li><li>Important for trades and becoming city-state suzerain.</li></ul><p>Early on gold seems unimportant, but ignoring it hurts: without a reserve (at least ~100g) to survive until Market tech, you can hit serious development trouble.</p><p>When gold goes negative, things get hard:</p><ul><li>Negative GPT reduces science each turn.</li><li>At -200 gold, the game automatically disbands one of your units — a major blow.</li></ul><p>So manage gold carefully and keep a reserve for critical moments.</p><h3 id="_1-4-science" tabindex="-1">1.4 Science <a class="header-anchor" href="#_1-4-science" aria-label="Permalink to &quot;1.4 Science&quot;">​</a></h3><p>Science unlocks technologies; pick your tech path based on terrain.</p><h3 id="_1-5-culture" tabindex="-1">1.5 Culture <a class="header-anchor" href="#_1-5-culture" aria-label="Permalink to &quot;1.5 Culture&quot;">​</a></h3><p>Culture unlocks social policies and expands city borders. E.g. a city&#39;s culture ring takes a horses tile, expanding after 1 turn.</p><h3 id="_1-6-happiness" tabindex="-1">1.6 Happiness <a class="header-anchor" href="#_1-6-happiness" aria-label="Permalink to &quot;1.6 Happiness&quot;">​</a></h3><p>Happiness is key to prosperity.</p><ul><li>When happiness accumulates enough, you can trigger a <strong>Golden Age</strong> with various bonuses.</li><li>Sources: improving luxury tiles and building happiness buildings.</li></ul><p>Negative effects:</p><ul><li>Happiness ≤ 0 → food yield -75%.</li><li>Happiness &lt; -10 → production -50%.</li></ul><p>Keep happiness positive and watch it closely.</p><h3 id="_1-7-faith" tabindex="-1">1.7 Faith <a class="header-anchor" href="#_1-7-faith" aria-label="Permalink to &quot;1.7 Faith&quot;">​</a></h3><p>Faith drives religion and special unlocks.</p><ul><li>A Pantheon needs accumulated faith; each new pantheon costs more.</li><li>Early faith mainly comes from the <strong>Shrine</strong> (26 production, 1 maintenance), but the payback is slow (at least 10 turns).</li></ul><p>Compared to other early investments:</p><ul><li><strong>Worker</strong>: no return for 10 turns, but high long-term production.</li><li><strong>Granary</strong>: fast payback, but limited by tiles and happiness.</li><li><strong>Settler</strong>: a new city pays back quickly, adds supply and military capability, but may lower happiness.</li></ul><p>Despite the Shrine&#39;s slow payback, some pantheons help long-term development a lot. <strong>Recommended early-war pantheons</strong>:</p><ul><li>God of the Open Sky (+culture)</li><li>God of Craftsmen (+production)</li><li>Desert Folklore (+faith)</li><li>Monument to the Gods (wonder speed)</li></ul><h3 id="_1-8-chapter-summary" tabindex="-1">1.8 Chapter summary <a class="header-anchor" href="#_1-8-chapter-summary" aria-label="Permalink to &quot;1.8 Chapter summary&quot;">​</a></h3><p>This chapter covered the six basic numbers — production, food, gold, science, culture, faith — their roles and downsides, plus their interrelations, and the key factor tied to them: <strong>population</strong>.</p><h2 id="_2-terrain-features-and-resources" tabindex="-1">2 Terrain, features and resources <a class="header-anchor" href="#_2-terrain-features-and-resources" aria-label="Permalink to &quot;2 Terrain, features and resources&quot;">​</a></h2><blockquote><p>Best read with the map editor open.</p></blockquote><h3 id="_2-1-terrain-and-features" tabindex="-1">2.1 Terrain and features <a class="header-anchor" href="#_2-1-terrain-and-features" aria-label="Permalink to &quot;2.1 Terrain and features&quot;">​</a></h3><p>Terrain splits into <strong>rough</strong> (forest, hills, jungle) and <strong>open</strong> (grassland, desert, ocean, etc.).</p><ul><li>Moving into rough terrain costs 2 movement; open costs 1.</li><li><strong>Marsh</strong> is special: open terrain, but costs 3 movement.</li><li><strong>Lakes</strong>: inland water; transported armies fight far worse — a natural barrier.</li></ul><p>Terrain modification:</p><ul><li>Workers can chop forest/jungle/marsh (tech required).</li><li>Chopping forest gives a one-time yield, priority: <ul><li>Inside borders, rings 1-2: 20 production</li><li>Inside borders, ring 3: 15</li><li>Outside borders, ring 2: 13</li><li>Outside borders, ring 3: 10</li><li>Outside borders, ring ≥4: 7</li></ul></li></ul><h4 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h4><p><img src="'+n+'" alt="Vision"></p><ul><li>All units see 2 tiles early.</li><li>Vision is affected by height: <strong>mountains &gt; hills &gt; open</strong>. <ul><li>Low units can&#39;t see behind high tiles.</li><li>Forest gives no height but blocks same-height vision.</li></ul></li><li><strong>Fun fact</strong>: standing on a mountain gives flatland vision (design quirk).</li><li>A tile one beyond your vision range is visible if it&#39;s higher than you with no same-height blocker in between.</li></ul><p><img src="'+l+'" alt="Vision example 1"><img src="'+d+'" alt="Vision example 2"></p><h3 id="_2-2-rivers" tabindex="-1">2.2 Rivers <a class="header-anchor" href="#_2-2-rivers" aria-label="Permalink to &quot;2.2 Rivers&quot;">​</a></h3><p>Rivers run between tiles, providing:</p><ul><li>+1 gold</li><li>Fresh water</li></ul><p>Strategic value:</p><ul><li>Crossing a river costs all movement.</li><li>Melee units attacking across a river get -20% strength.</li><li>Natural defensive barrier.</li></ul><h3 id="_2-3-resources" tabindex="-1">2.3 Resources <a class="header-anchor" href="#_2-3-resources" aria-label="Permalink to &quot;2.3 Resources&quot;">​</a></h3><p>Three kinds:</p><h4 id="bonus-resources" tabindex="-1">Bonus resources <a class="header-anchor" href="#bonus-resources" aria-label="Permalink to &quot;Bonus resources&quot;">​</a></h4><ul><li>Provide food and production only.</li><li><strong>Deer, wheat</strong> matter early — pair with the <strong>Granary</strong> for extra food.</li></ul><h4 id="luxury-resources" tabindex="-1">Luxury resources <a class="header-anchor" href="#luxury-resources" aria-label="Permalink to &quot;Luxury resources&quot;">​</a></h4><ul><li>Each kind gives <strong>4 happiness</strong> (duplicates don&#39;t stack).</li><li>Specials: <ul><li><strong>Salt</strong>: +1 yield after improvement.</li><li><strong>Marble</strong>: +15% wonder speed (not stackable).</li></ul></li></ul><h4 id="strategic-resources" tabindex="-1">Strategic resources <a class="header-anchor" href="#strategic-resources" aria-label="Permalink to &quot;Strategic resources&quot;">​</a></h4><ul><li>Needed for military units/upgrades.</li><li><strong>Horses</strong> are the early core: <ul><li>enable the Circus (+happiness)</li><li>required for Chariot Archers.</li></ul></li></ul><blockquote><p>Resource count decides development speed — settle near resources when possible.</p></blockquote><h2 id="_3-early-warfare" tabindex="-1">3 Early warfare <a class="header-anchor" href="#_3-early-warfare" aria-label="Permalink to &quot;3 Early warfare&quot;">​</a></h2><p><img src="'+u+'" alt="Early warfare"></p><p>Early military goals: <strong>scout, grab land, harass</strong>.</p><h3 id="_3-1-scouting" tabindex="-1">3.1 Scouting <a class="header-anchor" href="#_3-1-scouting" aria-label="Permalink to &quot;3.1 Scouting&quot;">​</a></h3><p>Goals:</p><ul><li>Find good second-city spots (rich resources, defensible, fast to support).</li><li>Locate enemy cities.</li></ul><blockquote><p>Hill cities have +5 defense and +1 production over plains — prefer hills for secondary cities.</p></blockquote><h3 id="_3-2-grabbing-land" tabindex="-1">3.2 Grabbing land <a class="header-anchor" href="#_3-2-grabbing-land" aria-label="Permalink to &quot;3.2 Grabbing land&quot;">​</a></h3><ul><li>Settlers are high-investment, high-return units; the earlier, the better.</li><li>Key spots often get contested.</li><li>Watch enemy zone of control (ZOC) to avoid extra movement costs.</li></ul><p><img src="'+c+'" alt="Zone of control"></p><h3 id="_3-3-harassing" tabindex="-1">3.3 Harassing <a class="header-anchor" href="#_3-3-harassing" aria-label="Permalink to &quot;3.3 Harassing&quot;">​</a></h3><ul><li>Disrupt enemy development.</li><li>Weaken their strength.</li><li>Create attack opportunities (small raids, damaging resource spots).</li></ul><h3 id="_3-4-chapter-summary" tabindex="-1">3.4 Chapter summary <a class="header-anchor" href="#_3-4-chapter-summary" aria-label="Permalink to &quot;3.4 Chapter summary&quot;">​</a></h3><p>Early military action revolves around scouting, grabbing land, and harassing — plan well to build an edge.</p><h2 id="_4-early-development" tabindex="-1">4 Early development <a class="header-anchor" href="#_4-early-development" aria-label="Permalink to &quot;4 Early development&quot;">​</a></h2><h3 id="_4-1-workers" tabindex="-1">4.1 Workers <a class="header-anchor" href="#_4-1-workers" aria-label="Permalink to &quot;4.1 Workers&quot;">​</a></h3><p>Workers are high-investment, high-return units. Uses:</p><ul><li><strong>Chopping forest/jungle</strong>: burst production (see table).</li><li><strong>Improving luxuries</strong> (when happiness is low).</li><li><strong>Improving strategics</strong> (when happiness is fine — e.g. horses, iron).</li></ul><table tabindex="0"><thead><tr><th>Chop target</th><th>Inside borders?</th><th>Distance to nearest city center</th><th>Burst production</th></tr></thead><tbody><tr><td>Forest</td><td>Yes</td><td>1</td><td>30</td></tr><tr><td>Forest</td><td>Yes</td><td>2</td><td>30</td></tr><tr><td>Forest</td><td>Yes</td><td>3</td><td>22</td></tr><tr><td>Forest</td><td>Yes</td><td>4</td><td>15</td></tr><tr><td>Forest</td><td>No</td><td>1</td><td>22</td></tr><tr><td>Forest</td><td>No</td><td>2</td><td>20</td></tr><tr><td>Forest</td><td>No</td><td>3</td><td>15</td></tr><tr><td>Forest</td><td>No</td><td>4</td><td>10</td></tr><tr><td>Jungle</td><td>Any</td><td>Any</td><td>0</td></tr></tbody></table><blockquote><p>Jungle chopping gives no production.</p></blockquote><h3 id="_4-2-citizen-control" tabindex="-1">4.2 Citizen control <a class="header-anchor" href="#_4-2-citizen-control" aria-label="Permalink to &quot;4.2 Citizen control&quot;">​</a></h3><p><img src="'+h+'" alt="Citizen control"></p><p>&quot;Controlling production&quot; means manually assigning which tiles citizens work.</p><ul><li>Auto-assignment prefers food, but with <strong>negative happiness</strong> food yield is -75%; auto still picks food, wasting domestic output.</li><li><strong>Solution</strong>: manually lock high-production tiles; as long as food keeps the population from starving, it&#39;s fine.</li><li>How: double-click a tile to lock it.</li></ul><h3 id="_4-3-buildings" tabindex="-1">4.3 Buildings <a class="header-anchor" href="#_4-3-buildings" aria-label="Permalink to &quot;4.3 Buildings&quot;">​</a></h3><p>Early building priority (typical order): <strong>Granary → Monument → Library → Shrine</strong></p><ul><li><strong>Monument</strong>: +2 culture, faster borders and policies.</li><li><strong>Granary</strong>: +food, indirectly more production (needs ≥2-food tiles and non-negative happiness).</li><li><strong>Shrine</strong>: opens pantheon/religion, but a Great Prophet needs 135 faith — long payback.</li><li><strong>Library</strong>: more science; limited use in early wars, consider when ahead.</li></ul><blockquote><p>Adjust to the situation — e.g. prioritize the Monument when happiness is low.</p></blockquote><h3 id="_4-4-policies" tabindex="-1">4.4 Policies <a class="header-anchor" href="#_4-4-policies" aria-label="Permalink to &quot;4.4 Policies&quot;">​</a></h3><p>Three main trees:</p><ul><li><strong>Tradition</strong>: weak in the current meta; not recommended.</li><li><strong>Liberty</strong>: suits wide players; speeds city development.</li><li><strong>Honor</strong>: explosive military power, near-unbeatable when strength gaps are large.</li></ul><p>Meta build: Honor into Liberty</p><ul><li>When: small maps with barbarians.</li><li>Effect: keeps Honor&#39;s 100% military burst plus Liberty&#39;s 75% development ability.</li><li>Support: build a Monument or pick &quot;God of the Open Sky&quot; for faster culture.</li></ul><h2 id="_5-mid-game-development" tabindex="-1">5 Mid-game development <a class="header-anchor" href="#_5-mid-game-development" aria-label="Permalink to &quot;5 Mid-game development&quot;">​</a></h2><h3 id="_5-1-buildings" tabindex="-1">5.1 Buildings <a class="header-anchor" href="#_5-1-buildings" aria-label="Permalink to &quot;5.1 Buildings&quot;">​</a></h3><p>In stalemates, add buildings to gain leverage:</p><ul><li><strong>Stable</strong>: <ul><li>+production on cattle/horses/sheep</li><li>+15% production toward mounted units</li></ul></li><li><strong>Stone Works</strong>: <ul><li>+1 happiness +1 production</li><li>+production on marble/granite tiles</li></ul></li><li><strong>Circus</strong>: <ul><li>needs horses or ivory</li><li>+2 happiness, cheaper than the Colosseum (17 less production on quick speed)</li></ul></li></ul><blockquote><p>Prioritize buildings matching your city&#39;s resources.</p></blockquote><ul><li><strong>Barracks</strong>: <ul><li>no domestic yield, but new units get +15 XP</li><li>1 gold maintenance</li><li>For: stable domestic + need elite melee (e.g. vs ranged-heavy enemies)</li><li>Terrain: pick promotions for plains/rough decisive points</li></ul></li></ul><h3 id="_5-2-roads" tabindex="-1">5.2 Roads <a class="header-anchor" href="#_5-2-roads" aria-label="Permalink to &quot;5.2 Roads&quot;">​</a></h3><p>Road advantages:</p><ol><li><strong>Fast military support</strong>: quick unit movement, breaking terrain limits (e.g. chariots can move-and-shoot on hills).</li><li><strong>Trade income</strong>: connecting capital to other cities yields gold.</li></ol><blockquote><p>Note: each road tile costs 1 gold maintenance. The shortest connection needs 3 tiles (cities can&#39;t be founded within 3 tiles), so a secondary city needs at least 3 population to cover road maintenance.</p></blockquote><p><strong>Conclusion</strong>: don&#39;t settle too spread out early.</p><h3 id="_5-3-wonders" tabindex="-1">5.3 Wonders <a class="header-anchor" href="#_5-3-wonders" aria-label="Permalink to &quot;5.3 Wonders&quot;">​</a></h3><p>Recommended:</p><ul><li>Great Library</li><li>Temple of Artemis</li><li>Petra</li><li>Hanging Gardens</li></ul><h2 id="_6-playing-the-situation" tabindex="-1">6 Playing the situation <a class="header-anchor" href="#_6-playing-the-situation" aria-label="Permalink to &quot;6 Playing the situation&quot;">​</a></h2><p>Domestic/tech unlocks need overall consideration:</p><ol><li><p><strong>Resource match</strong>:</p><ul><li>Many horses/cattle/sheep → prioritize Horseback Riding + Stable</li><li>Many camps/luxuries → prioritize Trapping + improvement</li></ul></li><li><p><strong>Terrain fit</strong>:</p><ul><li>Grassland → Horseback Riding/Stable</li><li>Forest → Forestry/lumber mills</li></ul></li><li><p><strong>Situation judgment</strong>:</p><ul><li>Control &gt; tech &gt; domestic</li><li>Behind → consider a military comeback</li><li>Ahead → focus on domestic accumulation</li></ul></li></ol><blockquote><p>Avoid researching irrelevant techs on wrong terrain — wasted resources.</p></blockquote><h2 id="_7-practice-game" tabindex="-1">7 Practice game <a class="header-anchor" href="#_7-practice-game" aria-label="Permalink to &quot;7 Practice game&quot;">​</a></h2><h3 id="_7-1-the-game" tabindex="-1">7.1 The game <a class="header-anchor" href="#_7-1-the-game" aria-label="Permalink to &quot;7.1 The game&quot;">​</a></h3><p><strong>Match</strong>: 恶 vs 陌生的云 祭楼源 (1v1 tiny duel)</p><ul><li>Rich opening: plenty of food tiles, but luxuries need Calendar tech; happiness low. <img src="'+p+'" alt=""></li><li>恶 opens <strong>Warrior first</strong> for stronger map control. <img src="'+g+'" alt=""></li><li>Meets the enemy Warrior; enemy Scout scouts.</li><li>恶 judges the south resource-poor and hard to support, abandons it, and instead <strong>goes around to block the enemy Settler</strong>. <img src="'+m+'" alt=""></li><li>Finds the north acceptable and easy to support — settles the second city there, using two Warriors to pressure and grab land.</li><li>Successfully blocks the enemy Settler for 2 turns; own Settler arrives safely.</li><li>Mountains block military advance, so switches to <strong>two-Worker chopping for domestic burst</strong>.</li><li>But luxuries are poor and the Granary underperforms; domestic is limited, so switches to a <strong>military rush</strong> — tech to Composite Bowman.</li><li>Despite leading in production (the enemy wasted production on a Granary), the rush <strong>fails due to mountains + river blocking</strong>.</li><li>The enemy exploits terrain to stall and mass-produces units to counter. <img src="'+b+'" alt=""><img src="'+y+'" alt=""><img src="'+f+'" alt=""><img src="'+k+'" alt=""><img src="'+v+'" alt=""><img src="'+_+'" alt=""></li></ul><h3 id="_7-2-review" tabindex="-1">7.2 Review <a class="header-anchor" href="#_7-2-review" aria-label="Permalink to &quot;7.2 Review&quot;">​</a></h3><ul><li><strong>恶</strong>: nearly perfect tempo and production lead, but terrain blocked both military and domestic plays — GG.</li><li><strong>Enemy</strong>: excellent terrain reading; winning from city placement, risked a greedy Granary but terrain bought enough time to win.</li></ul><h2 id="_8-extras" tabindex="-1">8 Extras <a class="header-anchor" href="#_8-extras" aria-label="Permalink to &quot;8 Extras&quot;">​</a></h2><h3 id="_8-1-honor-production-card" tabindex="-1">8.1 Honor production card <a class="header-anchor" href="#_8-1-honor-production-card" aria-label="Permalink to &quot;8.1 Honor production card&quot;">​</a></h3><p>Honor&#39;s left branch: <strong>melee units +15% production</strong>.</p><p>Unciv rounds production <strong>half-up</strong>:</p><ul><li>4 production → 3.4 → shows 3, actually saves 0.6</li><li>10 → 8.5 → shows 9, saves 1.5</li><li>17 → 14.45 → shows 15, saves 2</li></ul><blockquote><p>Usable for extreme production control.</p></blockquote><h3 id="_8-2-reloading-save-load" tabindex="-1">8.2 Reloading (save-load) <a class="header-anchor" href="#_8-2-reloading-save-load" aria-label="Permalink to &quot;8.2 Reloading (save-load)&quot;">​</a></h3><ul><li>Not happy with this turn&#39;s moves? Reload and redo.</li><li>Great for scouting: turns probabilistic events (Inca Slinger hits, Germany&#39;s barb-camp steals) into certainties.</li><li><strong>Note</strong>: damage rolls can&#39;t be changed by reloading.</li></ul><h3 id="_8-3-chopping" tabindex="-1">8.3 Chopping <a class="header-anchor" href="#_8-3-chopping" aria-label="Permalink to &quot;8.3 Chopping&quot;">​</a></h3><ul><li>Two Workers chopping two forests for the same city in the same turn triggers the production burst <strong>only once</strong>.</li></ul><h3 id="_8-4-decision-making" tabindex="-1">8.4 Decision-making <a class="header-anchor" href="#_8-4-decision-making" aria-label="Permalink to &quot;8.4 Decision-making&quot;">​</a></h3><p>Facing special terrain/situations, <strong>never blindly apply formulas</strong>.</p><ul><li>Analyze terrain (mountains: strong defense, slow movement; plains: fast but no cover).</li><li>Adjust to live info (e.g. the victory panel).</li><li>Avoid &quot;aimless play&quot;: when lost, pause, define goals, then act.</li><li>If the game is truly unwinnable, <strong>cut losses and restart</strong> — that&#39;s wisdom too.</li></ul><blockquote><p>Flexibility + independent thinking = unbeatable.</p></blockquote>',140)])])}const F=t(q,[["render",w]]);export{C as __pageData,F as default};
